import msgspec

class JobPayload(msgspec.Struct, frozen=True):
    job_id: str
    user_id: str
    payload: dict[str, str] = {}

def decode_job(raw: bytes) -> JobPayload:
    # Validation runs during decode
    return msgspec.json.decode(raw, type=JobPayload)

def encode_job(job: JobPayload) -> bytes:
    return msgspec.json.encode(job)

# MessagePack for internal bus
def encode_bus(job: JobPayload) -> bytes:
    return msgspec.msgpack.encode(job)

def decode_bus(raw: bytes) -> JobPayload:
    return msgspec.msgpack.decode(raw, type=JobPayload)

# Optional: convert Struct -> dict for Pydantic/HTTP edge
def job_to_public_dict(job: JobPayload) -> dict:
    return msgspec.to_builtins(job)
